BEFORE (vulnerable):
─────────────────────────────────────────
// Developer forgets tenant prefix
await _redis.SetAsync(
  $"course:{courseId}",   ← no tenant prefix
  data, TimeSpan.FromMinutes(30));

await _redis.GetAsync(
  $"course:{courseId}");  ← reads any tenant's data

AFTER (abstraction layer):
─────────────────────────────────────────
// TenantCache — the only Redis interface
// available to application code
public class TenantCache
{
  public Task SetAsync(
    string tenantId,      ← required, cannot omit
    string resource,
    object value,
    TimeSpan ttl)
  {
    var key = $"tenant:{tenantId}:{resource}";
    return _redis.SetAsync(key, value, ttl);
  }

  public Task<T> GetAsync<T>(
    string tenantId,      ← required
    string resource)
  {
    var key = $"tenant:{tenantId}:{resource}";
    return _redis.GetAsync<T>(key);
  }
}

// Application code — cannot construct raw keys
await _tenantCache.SetAsync(
  tenantId, $"course:{courseId}", data, ttl);

DETECTION (Application Insights):
─────────────────────────────────────────
// Custom metric on every Redis operation
// Alert if key does not start with tenant:
Kusto query (runs every 5 minutes):
customMetrics
| where name == "RedisKeyWrite"
| where tostring(customDimensions.key)
    !startswith "tenant:"
| project timestamp, key, tenantId, operation
→ Alert: fire PagerDuty immediately

IMMEDIATE REMEDIATION:
─────────────────────────────────────────
// One-time audit — find all mis-namespaced keys
SCAN pattern: *  (all keys)
Filter: keys NOT matching tenant:*
Action: DELETE each mis-namespaced key
Log: { key, deletedAt, auditRunId }

